import{_ as t,o as e,c as i,a2 as d}from"./chunks/framework.BXzK3EA4.js";const s=JSON.parse('{"title":"캠페인 루프와 진행 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Rules-CampaignLoop.md","filePath":"rules/Rules-CampaignLoop.md"}'),r={name:"rules/Rules-CampaignLoop.md"};function l(o,a,c,n,h,p){return e(),i("div",null,[...a[0]||(a[0]=[d('<h1 id="캠페인-루프와-진행-규칙" tabindex="-1">캠페인 루프와 진행 규칙 <a class="header-anchor" href="#캠페인-루프와-진행-규칙" aria-label="Permalink to &quot;캠페인 루프와 진행 규칙&quot;">​</a></h1><blockquote><p>출처: docs/game-logic/Campaign-Loop.md, docs/game-logic/Campaign-Progression.md — 계약 수치는 구현 상수를 우선한다.</p></blockquote><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>캠페인 한 사이클은 거점 준비부터 결과 반영까지 여섯 단계로만 돈다. 시간은 행동→시간→하루→한주 사다리를 탄다. 진행 측정은 영토 숫자가 아니라 거점 안정화와 전문화와 연결 투사력과 정통성이다.</p><h2 id="핵심-수치" tabindex="-1">핵심 수치 <a class="header-anchor" href="#핵심-수치" aria-label="Permalink to &quot;핵심 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th style="text-align:right;">값</th><th>범위·한도</th></tr></thead><tbody><tr><td>안보 <code>S_i</code></td><td style="text-align:right;">안정 거점 70</td><td>0~100</td></tr><tr><td>기능 <code>F_i</code></td><td style="text-align:right;">안정 거점 70</td><td>0~100</td></tr><tr><td>정통성 <code>L_i</code></td><td style="text-align:right;">안정 거점 60</td><td>0~100</td></tr><tr><td>연결 <code>K_i</code></td><td style="text-align:right;"><code>clamp(max_path(경로신뢰도), 0, 1)</code></td><td>0~1</td></tr><tr><td>부족 <code>x_i</code></td><td style="text-align:right;">수요 0이면 0</td><td>0~1</td></tr><tr><td>과확장 <code>O</code></td><td style="text-align:right;">공유 척도 유지</td><td>0~2</td></tr><tr><td>긴장도 <code>E</code></td><td style="text-align:right;">시작 20</td><td>0~100</td></tr><tr><td>회복</td><td style="text-align:right;"><code>clamp(10 + 10*위기해결품질, 0, 20)</code></td><td>미해결 주 0</td></tr><tr><td>위기확률</td><td style="text-align:right;"><code>clamp(0.10 + 0.01*(E-50) + 0.15*O + 0.10*평균부족 + 0.10*평균고립, 0.10, 0.75)</code></td><td>10%~75%</td></tr><tr><td>신규 점령 확장 충격</td><td style="text-align:right;">5</td><td>0~10</td></tr><tr><td>부족 임계</td><td style="text-align:right;">0.25</td><td>0~1</td></tr><tr><td>심각 부족 임계</td><td style="text-align:right;">0.75</td><td>0~1</td></tr><tr><td>강제 대응까지 심각 부족</td><td style="text-align:right;">3일</td><td>1일~7일</td></tr><tr><td>붕괴 선택까지 심각 부족</td><td style="text-align:right;">7일</td><td>3일~14일</td></tr><tr><td>거점 가중치 일반</td><td style="text-align:right;">1.0</td><td>분모 하한 0.25</td></tr><tr><td>거점 가중치 환승</td><td style="text-align:right;">1.5</td><td>분모 하한 0.25</td></tr><tr><td>계열 부족·오염</td><td style="text-align:right;"><code>1 + 4*평균부족</code></td><td>설계 가정</td></tr><tr><td>계열 고립·정전·경로 탈취</td><td style="text-align:right;"><code>1 + 4*평균고립</code></td><td>설계 가정</td></tr><tr><td>계열 과확장·분열·다면 전선 약탈</td><td style="text-align:right;"><code>1 + 4*min(O, 1)</code></td><td>설계 가정</td></tr><tr><td>계열 외부 충격</td><td style="text-align:right;"><code>1 + E/100</code></td><td>설계 가정</td></tr><tr><td>대상 가중치</td><td style="text-align:right;"><code>거점가중치_i * (1 + 2*부족_i + 2*고립_i + (1 - min(S_i, F_i, L_i) / 100))</code></td><td>—</td></tr><tr><td>예시 긴장도</td><td style="text-align:right;">58</td><td>—</td></tr><tr><td>예시 과확장</td><td style="text-align:right;">0.5</td><td>—</td></tr><tr><td>예시 평균 부족</td><td style="text-align:right;">0.139</td><td>—</td></tr><tr><td>예시 평균 고립</td><td style="text-align:right;">0.2</td><td>—</td></tr><tr><td>예시 위기확률</td><td style="text-align:right;">0.2889</td><td>28.89%</td></tr><tr><td>예시 해결 품질</td><td style="text-align:right;">0.8</td><td>0~1</td></tr><tr><td>예시 회복</td><td style="text-align:right;">18</td><td>—</td></tr></tbody></table><h2 id="조항" tabindex="-1">조항 <a class="header-anchor" href="#조항" aria-label="Permalink to &quot;조항&quot;">​</a></h2><h3 id="rcampaign-01-사이클은-한-줄로만-돈다" tabindex="-1">RCAMPAIGN-01 사이클은 한 줄로만 돈다 <a class="header-anchor" href="#rcampaign-01-사이클은-한-줄로만-돈다" aria-label="Permalink to &quot;RCAMPAIGN-01 사이클은 한 줄로만 돈다&quot;">​</a></h3><p>캠페인 한 사이클에서 준비와 원정과 조우와 전투와 결과 반영을 이 순서로만 진행한다. 앞 단계가 닫히기 전에 다음 단계를 열지 않는다.</p><h3 id="rcampaign-02-단계는-여섯이다" tabindex="-1">RCAMPAIGN-02 단계는 여섯이다 <a class="header-anchor" href="#rcampaign-02-단계는-여섯이다" aria-label="Permalink to &quot;RCAMPAIGN-02 단계는 여섯이다&quot;">​</a></h3><p>순서는 거점에서 할 일 고르기, 원정 준비, 4방향 원정, 마주친 일 풀기, 전술 전투, 결과 반영이다. 여섯을 늘리거나 줄이지 않는다.</p><h3 id="rcampaign-03-거점에서-할-일을-먼저-고른다" tabindex="-1">RCAMPAIGN-03 거점에서 할 일을 먼저 고른다 <a class="header-anchor" href="#rcampaign-03-거점에서-할-일을-먼저-고른다" aria-label="Permalink to &quot;RCAMPAIGN-03 거점에서 할 일을 먼저 고른다&quot;">​</a></h3><p>거점에서는 정보와 의뢰와 계약과 관계 문제를 살핀다. 원정 준비는 그 선택이 끝난 뒤에만 연다.</p><h3 id="rcampaign-04-원정-준비를-빠뜨리지-않는다" tabindex="-1">RCAMPAIGN-04 원정 준비를 빠뜨리지 않는다 <a class="header-anchor" href="#rcampaign-04-원정-준비를-빠뜨리지-않는다" aria-label="Permalink to &quot;RCAMPAIGN-04 원정 준비를 빠뜨리지 않는다&quot;">​</a></h3><p>파티와 장비와 식량과 의약품과 경로와 통행권을 준비한다. 비어 있는 항목으로 4방향 원정에 나서지 않는다.</p><h3 id="rcampaign-05-원정은-같은-격자에서-네-방향으로-간다" tabindex="-1">RCAMPAIGN-05 원정은 같은 격자에서 네 방향으로 간다 <a class="header-anchor" href="#rcampaign-05-원정은-같은-격자에서-네-방향으로-간다" aria-label="Permalink to &quot;RCAMPAIGN-05 원정은 같은 격자에서 네 방향으로 간다&quot;">​</a></h3><p>지상과 역사와 터널을 같은 아이소메트릭 격자에서 이동한다. 원정 층을 다른 규칙판으로 갈아타지 않는다.</p><h3 id="rcampaign-06-조우는-전투-전에-푼다" tabindex="-1">RCAMPAIGN-06 조우는 전투 전에 푼다 <a class="header-anchor" href="#rcampaign-06-조우는-전투-전에-푼다" aria-label="Permalink to &quot;RCAMPAIGN-06 조우는 전투 전에 푼다&quot;">​</a></h3><p>마주친 일에서는 교섭이나 거래나 작업이나 은신이나 회피나 전투를 고른다. 전투는 그 선택지 중 하나일 뿐이며 기본값이 아니다.</p><h3 id="rcampaign-07-결정적-충돌만-전술로-넘긴다" tabindex="-1">RCAMPAIGN-07 결정적 충돌만 전술로 넘긴다 <a class="header-anchor" href="#rcampaign-07-결정적-충돌만-전술로-넘긴다" aria-label="Permalink to &quot;RCAMPAIGN-07 결정적 충돌만 전술로 넘긴다&quot;">​</a></h3><p>결정적 충돌은 같은 격자의 실시간 진형·카드 규칙으로 해결한다. 사소한 마찰을 전술판으로 끌어오지 않는다.</p><h3 id="rcampaign-08-결과는-거점과-노선까지-반영한다" tabindex="-1">RCAMPAIGN-08 결과는 거점과 노선까지 반영한다 <a class="header-anchor" href="#rcampaign-08-결과는-거점과-노선까지-반영한다" aria-label="Permalink to &quot;RCAMPAIGN-08 결과는 거점과 노선까지 반영한다&quot;">​</a></h3><p>복귀하면 부상과 시간과 물자와 관계와 평판과 거점과 노선 상태가 바뀐다. 전투 승패만 남기고 세계를 그대로 두지 않는다.</p><h3 id="rcampaign-09-규모는-인물과-사건으로만-커진다" tabindex="-1">RCAMPAIGN-09 규모는 인물과 사건으로만 커진다 <a class="header-anchor" href="#rcampaign-09-규모는-인물과-사건으로만-커진다" aria-label="Permalink to &quot;RCAMPAIGN-09 규모는 인물과 사건으로만 커진다&quot;">​</a></h3><p>초기는 파티 생존과 한 역의 문제를 다룬다. 신뢰와 직능을 얻은 뒤에는 작업반이나 상단을 이끌고 이후에는 여러 역의 협약과 노선 세력의 정책에 개입한다. 규모가 커져도 선택은 이름 있는 인물과 구체적인 사건을 통해 전달된다.</p><h3 id="rcampaign-10-시간-사다리는-행동→시간→하루→한주다" tabindex="-1">RCAMPAIGN-10 시간 사다리는 행동→시간→하루→한주다 <a class="header-anchor" href="#rcampaign-10-시간-사다리는-행동→시간→하루→한주다" aria-label="Permalink to &quot;RCAMPAIGN-10 시간 사다리는 행동→시간→하루→한주다&quot;">​</a></h3><p>행동은 한 칸 이동과 대화와 작업과 공격 같은 즉시 결정이다. 시간은 이동과 피로와 식량과 지역 일정을 먹고 하루는 역 생산과 소비와 외부 파티 이동과 노선 안전을 집계한다. 한주는 외교와 인구 집계와 정통성과 세력 목표를 돌린다.</p><h3 id="rcampaign-11-정밀도는-거리로-가른다" tabindex="-1">RCAMPAIGN-11 정밀도는 거리로 가른다 <a class="header-anchor" href="#rcampaign-11-정밀도는-거리로-가른다" aria-label="Permalink to &quot;RCAMPAIGN-11 정밀도는 거리로 가른다&quot;">​</a></h3><p>플레이어 주변은 자세히 계산한다. 멀리 있는 세계는 집계 단위로 처리하며 세계 전체를 같은 정밀도로 계속 계산하지 않는다.</p><h3 id="rcampaign-12-진행은-영토-숫자가-아니다" tabindex="-1">RCAMPAIGN-12 진행은 영토 숫자가 아니다 <a class="header-anchor" href="#rcampaign-12-진행은-영토-숫자가-아니다" aria-label="Permalink to &quot;RCAMPAIGN-12 진행은 영토 숫자가 아니다&quot;">​</a></h3><p>진행은 거점의 안정화와 전문화와 연결 투사력과 플레이어가 세운 질서의 정당성으로 측정한다. 점령 칸을 승점으로 바꾸지 않는다.</p><h3 id="rcampaign-13-연결-k-i는-경로-신뢰도의-최댓값을-자른다" tabindex="-1">RCAMPAIGN-13 연결 <code>K_i</code>는 경로 신뢰도의 최댓값을 자른다 <a class="header-anchor" href="#rcampaign-13-연결-k-i는-경로-신뢰도의-최댓값을-자른다" aria-label="Permalink to &quot;RCAMPAIGN-13 연결 `K_i`는 경로 신뢰도의 최댓값을 자른다&quot;">​</a></h3><p><code>K_i = clamp(max_path(경로신뢰도), 0, 1)</code>이다. 구호와 교역과 증원 가능성은 이 값에서만 읽는다.</p><h3 id="rcampaign-14-부족은-수요-0에서-나누지-않는다" tabindex="-1">RCAMPAIGN-14 부족은 수요 0에서 나누지 않는다 <a class="header-anchor" href="#rcampaign-14-부족은-수요-0에서-나누지-않는다" aria-label="Permalink to &quot;RCAMPAIGN-14 부족은 수요 0에서 나누지 않는다&quot;">​</a></h3><p>수요가 0이면 부족_i는 0이다. 아니면 <code>1 - clamp(가용량 / 수요, 0, 1)</code>이며 범위는 0~1로 남는다.</p><h3 id="rcampaign-15-긴장도-e-는-한-식에-모은다" tabindex="-1">RCAMPAIGN-15 긴장도 <code>E&#39;</code>는 한 식에 모은다 <a class="header-anchor" href="#rcampaign-15-긴장도-e-는-한-식에-모은다" aria-label="Permalink to &quot;RCAMPAIGN-15 긴장도 `E&#39;`는 한 식에 모은다&quot;">​</a></h3><p><code>E&#39; = clamp(E + 시간압력 + 확장충격 + 부족 + 고립 + 과확장 - 회복, 0, 100)</code>이다. 시작 긴장도는 20이고 신규 점령 확장 충격 기본값은 5다.</p><h3 id="rcampaign-16-위기확률은-0-10과-0-75-사이에-가둔다" tabindex="-1">RCAMPAIGN-16 위기확률은 0.10과 0.75 사이에 가둔다 <a class="header-anchor" href="#rcampaign-16-위기확률은-0-10과-0-75-사이에-가둔다" aria-label="Permalink to &quot;RCAMPAIGN-16 위기확률은 0.10과 0.75 사이에 가둔다&quot;">​</a></h3><p><code>위기확률 = clamp(0.10 + 0.01*(E-50) + 0.15*O + 0.10*평균부족 + 0.10*평균고립, 0.10, 0.75)</code>이다. 기본 위기 확률은 10%이고 최댓값은 75%다.</p><h3 id="rcampaign-17-평균은-거점-가중치로-낸다" tabindex="-1">RCAMPAIGN-17 평균은 거점 가중치로 낸다 <a class="header-anchor" href="#rcampaign-17-평균은-거점-가중치로-낸다" aria-label="Permalink to &quot;RCAMPAIGN-17 평균은 거점 가중치로 낸다&quot;">​</a></h3><p><code>평균부족</code>과 <code>평균고립</code>은 거점 가중치 가중 평균이며 분모 하한은 0.25다. 일반 거점 가중치는 1.0이고 환승은 1.5이며 과확장 척도 자체는 바꾸지 않는다.</p><h3 id="rcampaign-18-회복은-그-주-해결에만-붙는다" tabindex="-1">RCAMPAIGN-18 회복은 그 주 해결에만 붙는다 <a class="header-anchor" href="#rcampaign-18-회복은-그-주-해결에만-붙는다" aria-label="Permalink to &quot;RCAMPAIGN-18 회복은 그 주 해결에만 붙는다&quot;">​</a></h3><p><code>회복 = clamp(10 + 10*위기해결품질, 0, 20)</code>이다. 해결 품질은 0~1이고 그 주에 위기를 해결하지 못하면 회복은 0이다.</p><h3 id="rcampaign-19-위기-종류와-대상은-원장에-남긴다" tabindex="-1">RCAMPAIGN-19 위기 종류와 대상은 원장에 남긴다 <a class="header-anchor" href="#rcampaign-19-위기-종류와-대상은-원장에-남긴다" aria-label="Permalink to &quot;RCAMPAIGN-19 위기 종류와 대상은 원장에 남긴다&quot;">​</a></h3><p>위기 종류와 대상은 캠페인 시드와 주차와 전용 난수 흐름으로 결정한다. 원인 가중치를 원장에 기록하기 전에는 위기를 확정하지 않는다.</p><h3 id="rcampaign-20-계열-가중치는-원인별로-갈린다" tabindex="-1">RCAMPAIGN-20 계열 가중치는 원인별로 갈린다 <a class="header-anchor" href="#rcampaign-20-계열-가중치는-원인별로-갈린다" aria-label="Permalink to &quot;RCAMPAIGN-20 계열 가중치는 원인별로 갈린다&quot;">​</a></h3><p>부족·오염은 <code>1 + 4*평균부족</code>이다. 고립·정전·경로 탈취는 <code>1 + 4*평균고립</code>이고 과확장·분열·다면 전선 약탈은 <code>1 + 4*min(O, 1)</code>이며 외부 충격은 <code>1 + E/100</code>이다.</p><h3 id="rcampaign-21-대상-가중치는-약한-거점으로-기운다" tabindex="-1">RCAMPAIGN-21 대상 가중치는 약한 거점으로 기운다 <a class="header-anchor" href="#rcampaign-21-대상-가중치는-약한-거점으로-기운다" aria-label="Permalink to &quot;RCAMPAIGN-21 대상 가중치는 약한 거점으로 기운다&quot;">​</a></h3><p>대상 가중치는 <code>거점가중치_i * (1 + 2*부족_i + 2*고립_i + (1 - min(S_i, F_i, L_i) / 100))</code>이다. 안보와 기능과 정통성 중 가장 낮은 값이 낮을수록 그 거점이 먼저 맞는다.</p><h3 id="rcampaign-22-심각-부족은-날짜로-강제한다" tabindex="-1">RCAMPAIGN-22 심각 부족은 날짜로 강제한다 <a class="header-anchor" href="#rcampaign-22-심각-부족은-날짜로-강제한다" aria-label="Permalink to &quot;RCAMPAIGN-22 심각 부족은 날짜로 강제한다&quot;">​</a></h3><p>부족 임계는 0.25이고 심각 부족 임계는 0.75다. 심각 부족 3일은 강제 지역 비상사건을 열고 7일은 철수·배급 강제·항복 협상·지역 붕괴 선택을 연다.</p><h3 id="rcampaign-23-고립과-과확장은-지연으로만-드러난다" tabindex="-1">RCAMPAIGN-23 고립과 과확장은 지연으로만 드러난다 <a class="header-anchor" href="#rcampaign-23-고립과-과확장은-지연으로만-드러난다" aria-label="Permalink to &quot;RCAMPAIGN-23 고립과 과확장은 지연으로만 드러난다&quot;">​</a></h3><p>고립된 거점은 비축으로 버틸 수 있으나 증인과 구호와 수리 인력이 오지 않아 회복이 느리다. 과확장은 적을 마법처럼 강화하지 않고 모든 거점의 행정·순찰·수리 지연으로 나타난다.</p><h3 id="rcampaign-24-성장-경로는-헌장까지-이어진다" tabindex="-1">RCAMPAIGN-24 성장 경로는 헌장까지 이어진다 <a class="header-anchor" href="#rcampaign-24-성장-경로는-헌장까지-이어진다" aria-label="Permalink to &quot;RCAMPAIGN-24 성장 경로는 헌장까지 이어진다&quot;">​</a></h3><p>점령 다음은 안정화이고 그다음은 전문화와 노선 투사와 질서 헌장이다. 안정화 실패와 노선 투사 과확장은 회복 태세로 떨어지고 회복 태세는 다시 안정화로만 돌아간다. 질서 헌장은 다중 결말 평가로 넘어간다.</p><h3 id="rcampaign-25-같은-주-여러-위기는-식별자-순이다" tabindex="-1">RCAMPAIGN-25 같은 주 여러 위기는 식별자 순이다 <a class="header-anchor" href="#rcampaign-25-같은-주-여러-위기는-식별자-순이다" aria-label="Permalink to &quot;RCAMPAIGN-25 같은 주 여러 위기는 식별자 순이다&quot;">​</a></h3><p>같은 주에 여러 위기가 발생하면 전용 난수 결과를 고정한 뒤 위기 ID 순서로 예약한다. 난수를 다시 굴려 순서를 바꾸지 않는다.</p><h3 id="rcampaign-26-승리는-헌장-조건으로-연다" tabindex="-1">RCAMPAIGN-26 승리는 헌장 조건으로 연다 <a class="header-anchor" href="#rcampaign-26-승리는-헌장-조건으로-연다" aria-label="Permalink to &quot;RCAMPAIGN-26 승리는 헌장 조건으로 연다&quot;">​</a></h3><p>승리는 서울 통일 하나가 아니다. 노선 연합이나 독립 역 협약이나 교역 질서나 기술 복구 같은 헌장 조건으로 평가한다.</p><h3 id="rcampaign-27-예시-수치는-공식-검산용이다" tabindex="-1">RCAMPAIGN-27 예시 수치는 공식 검산용이다 <a class="header-anchor" href="#rcampaign-27-예시-수치는-공식-검산용이다" aria-label="Permalink to &quot;RCAMPAIGN-27 예시 수치는 공식 검산용이다&quot;">​</a></h3><p>긴장도 58과 과확장 0.5와 평균 부족 0.139와 평균 고립 0.2이면 위기확률은 0.2889다. 해결 품질 0.8이면 그 주 회복은 18이며 이 값은 <code>E&#39;</code>의 차감 항으로만 쓴다. 같은 주의 시간압력·확장충격·부족·고립·과확장 증가 항이 모두 0일 때만 <code>E&#39;=E-18</code>이 된다.</p><h2 id="판정-순서" tabindex="-1">판정 순서 <a class="header-anchor" href="#판정-순서" aria-label="Permalink to &quot;판정 순서&quot;">​</a></h2><ol><li>거점에서 정보와 의뢰와 계약과 관계 문제를 살피고 할 일을 고른다.</li><li>파티와 장비와 식량과 의약품과 경로와 통행권을 채운 뒤에만 원정을 연다.</li><li>같은 아이소메트릭 격자에서 지상과 역사와 터널을 이동한다.</li><li>조우가 뜨면 교섭이나 거래나 작업이나 은신이나 회피나 전투 중 하나를 택한다.</li><li>결정적 충돌만 같은 격자의 실시간 진형·카드 규칙으로 푼다.</li><li>부상과 시간과 물자와 관계와 평판과 거점과 노선 상태를 반영하고 사이클을 닫는다.</li><li>행동 결과를 시간으로 올리고 하루 집계를 거친 뒤 한주로 넘긴다.</li><li><code>K_i</code>를 경로 신뢰도 최댓값으로 자르고 부족_i를 계산한다. 수요 0이면 부족은 0이다.</li><li>거점 가중치로 평균부족과 평균고립을 낸다. 분모는 0.25 아래로 내리지 않는다.</li><li>위기확률 공식에 긴장도와 과확장과 평균부족과 평균고립을 넣고 0.10~0.75로 가둔다.</li><li>시드와 주차와 전용 난수 흐름으로 종류와 대상을 고르고 계열 가중치와 대상 가중치를 원장에 기록한다.</li><li>같은 주에 여러 건이면 난수 결과를 고정한 뒤 위기 ID 순서로 예약한다.</li><li>그 주에 해결한 경우에만 회복을 빼고 <code>E&#39;</code>를 0~100으로 자른다. 미해결이면 회복은 0이다.</li><li>심각 부족이 3일이면 강제 지역 비상사건을 연다. 7일이면 철수·배급 강제·항복 협상·지역 붕괴 선택을 연다.</li><li>질서 헌장에 도달하면 노선 연합과 독립 역 협약과 교역 질서와 기술 복구 조건으로 결말을 평가한다.</li></ol><h2 id="금지-사항" tabindex="-1">금지 사항 <a class="header-anchor" href="#금지-사항" aria-label="Permalink to &quot;금지 사항&quot;">​</a></h2><ul><li>여섯 단계를 건너뛰거나 한 사이클 안에서 병렬로 겹치지 않는다.</li><li>세계 전체를 같은 정밀도로 계속 계산하지 않는다.</li><li>수요 0인 항목을 나누지 않는다. 그 부족은 0이다.</li><li>위기를 해결하지 않은 주에 회복을 넣지 않는다.</li><li>과확장으로 적을 강화하지 않는다. 행정과 순찰과 수리만 늦춘다.</li><li>같은 주 여러 위기의 난수를 다시 굴려 순서를 바꾸지 않는다.</li><li>승리를 서울 통일 하나로 닫지 않는다.</li><li>과확장 척도 0~2를 다른 범위로 바꾸지 않는다.</li><li>가중 평균 분모 하한 0.25를 무시하지 않는다.</li><li>원인 가중치를 원장에 남기지 않고 위기를 확정하지 않는다.</li><li>점령 칸 수를 진행 점수로 쓰지 않는다.</li><li>안정화 실패나 과확장 뒤 회복 태세를 건너뛰고 헌장으로 점프하지 않는다.</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><ul><li><code>docs/game-logic/Campaign-Loop.md</code> — 여섯 단계와 시간 사다리와 규모 확대.</li><li><code>docs/game-logic/Campaign-Progression.md</code> — 입력 지표와 공식과 기본 수치와 경계. 본문 표기는 설계 가정.</li><li>수치 충돌: 두 출처 사이에 어긋나는 값은 없다. 계약/잠긴 표기도 없다. 진행 수치는 설계 가정이므로 구현 상수가 생기면 그 값을 우선한다.</li><li>검산 고정: 긴장도 58, 과확장 0.5, 평균 부족 0.139, 평균 고립 0.2 → 위기확률 0.2889. 해결 품질 0.8 → 회복 18.</li></ul>',67)])])}const m=t(r,[["render",l]]);export{s as __pageData,m as default};
